def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]
    color = 2
    for c in range(c0, c1 + 1):
        if out[r0][c] == bg:
            out[r0][c] = color
        if out[r1][c] == bg:
            out[r1][c] = color
    for r in range(r0, r1 + 1):
        if out[r][c0] == bg:
            out[r][c0] = color
        if out[r][c1] == bg:
            out[r][c1] = color
    return out
